<?php
namespace App\Services;
use App\Models\Category; use App\Models\Product; use Illuminate\Support\Str; use PhpOffice\PhpSpreadsheet\IOFactory;
class BulkProductImporter { public function import(string $path):array{$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$rows=[]; if($ext==='csv'){ $h=fopen($path,'r');$headers=fgetcsv($h);while(($r=fgetcsv($h))!==false){$rows[]=array_combine($headers,$r);}fclose($h);} else {$sheet=IOFactory::load($path)->getActiveSheet()->toArray(null,true,true,true);$header=array_shift($sheet);$keys=array_values($header);foreach($sheet as $r){$vals=array_values($r);if(array_filter($vals,fn($v)=>$v!==null&&$v!==''))$rows[]=array_combine($keys,$vals);}} $ok=0;$errors=[];foreach($rows as $i=>$row){try{$name=trim((string)($row['Product Name']??$row['name']??''));$sku=trim((string)($row['SKU']??$row['sku']??''));if(!$name||!$sku)throw new \RuntimeException('Product Name and SKU are required');$catName=trim((string)($row['Category']??'Uncategorised'));$cat=Category::firstOrCreate(['slug'=>Str::slug($catName)],['name'=>$catName]);Product::updateOrCreate(['sku'=>$sku],['category_id'=>$cat->id,'name'=>$name,'slug'=>Str::slug($name.'-'.$sku),'price'=>(float)($row['Price']??0),'stock'=>(int)($row['Stock']??0),'description'=>$row['Description']??null,'material'=>$row['Material']??null,'is_active'=>strtolower((string)($row['Status']??'active'))!=='inactive']);$ok++;}catch(\Throwable $e){$errors[]=['row'=>$i+2,'message'=>$e->getMessage()];}}return ['imported'=>$ok,'errors'=>$errors,'total'=>count($rows)];} }
